package main

const schema = `
CREATE TABLE IF NOT EXISTS users (
 id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE COLLATE NOCASE,username TEXT NOT NULL UNIQUE COLLATE NOCASE,
 role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('admin','reviewer','member')),points INTEGER NOT NULL DEFAULT 0,credits INTEGER NOT NULL DEFAULT 10 CHECK(credits>=0),
 week_key TEXT NOT NULL DEFAULT '',weekly_used INTEGER NOT NULL DEFAULT 0,contributions INTEGER NOT NULL DEFAULT 0,featured_contributions INTEGER NOT NULL DEFAULT 0,rare_contributions INTEGER NOT NULL DEFAULT 0,
 last_quality_at TEXT NOT NULL DEFAULT '',disabled INTEGER NOT NULL DEFAULT 0,membership_until TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,
 paid_tier INTEGER NOT NULL DEFAULT 0,paid_until TEXT NOT NULL DEFAULT '',
 day_key TEXT NOT NULL DEFAULT '',daily_used INTEGER NOT NULL DEFAULT 0 CHECK(daily_used>=0),
 CHECK(role!='admin' OR email='1402272093@qq.com')
);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS test_accounts(owner_id INTEGER PRIMARY KEY REFERENCES users(id),user_id INTEGER NOT NULL UNIQUE REFERENCES users(id));
CREATE TABLE IF NOT EXISTS test_sessions(session_hash TEXT PRIMARY KEY REFERENCES sessions(token_hash) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS invites(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE,max_uses INTEGER NOT NULL DEFAULT 1,uses INTEGER NOT NULL DEFAULT 0,expires_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,permanent INTEGER NOT NULL DEFAULT 0 CHECK(permanent IN (0,1)),created_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_codes(email TEXT PRIMARY KEY,code_hash TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,ip TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS code_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL,ip TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS code_requests_time ON code_requests(created_at);
CREATE TABLE IF NOT EXISTS gaps(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL,category TEXT NOT NULL,level TEXT NOT NULL DEFAULT 'ordinary',evidence TEXT NOT NULL,source_name TEXT NOT NULL,source_url TEXT NOT NULL UNIQUE,source_visibility TEXT NOT NULL DEFAULT 'public' CHECK(source_visibility IN ('public','internal')),published_at TEXT NOT NULL,released_at TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',tags TEXT NOT NULL DEFAULT '[]',author_id INTEGER REFERENCES users(id),review_note TEXT NOT NULL DEFAULT '',rewarded INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS gaps_status_time ON gaps(status,published_at DESC);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,last_attempt TEXT,last_success TEXT,last_error TEXT NOT NULL DEFAULT '',last_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS unlocks(user_id INTEGER NOT NULL REFERENCES users(id),gap_id INTEGER NOT NULL REFERENCES gaps(id),cost INTEGER NOT NULL DEFAULT 0,kind TEXT NOT NULL,created_at TEXT NOT NULL,refunded INTEGER NOT NULL DEFAULT 0,daily_cost INTEGER NOT NULL DEFAULT 0,day_key TEXT NOT NULL DEFAULT '',PRIMARY KEY(user_id,gap_id));
CREATE TABLE IF NOT EXISTS saves(user_id INTEGER NOT NULL REFERENCES users(id),gap_id INTEGER NOT NULL REFERENCES gaps(id),created_at TEXT NOT NULL,PRIMARY KEY(user_id,gap_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),gap_id INTEGER NOT NULL REFERENCES gaps(id),reason TEXT NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',UNIQUE(user_id,gap_id));
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),gap_id INTEGER REFERENCES gaps(id),kind TEXT NOT NULL,amount INTEGER NOT NULL,created_at TEXT NOT NULL,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contribution_rewards(gap_id INTEGER PRIMARY KEY REFERENCES gaps(id),user_id INTEGER NOT NULL REFERENCES users(id),points INTEGER NOT NULL,featured INTEGER NOT NULL,rare INTEGER NOT NULL,awarded_at TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('category','tag')),value TEXT NOT NULL COLLATE NOCASE,created_at TEXT NOT NULL,UNIQUE(user_id,kind,value));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,object_id TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS summary_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,gap_id INTEGER NOT NULL UNIQUE REFERENCES gaps(id),content_hash TEXT NOT NULL,title TEXT NOT NULL,source_text TEXT NOT NULL,original_body_hash TEXT NOT NULL,original_updated_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,last_attempt TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);
`
